def links(slug, routes):
    out, i = [], 0
    while len(out) < 2 and i < 30:
        r = routes[(sum(ord(c) for c in slug) + 7 * i) % len(routes)]
        if r.split('/')[-1] != slug and r not in out:
            out.append(r)
        i += 1
    return out

def see3(slug, routes):
    out, i = [], 0
    while len(out) < 3 and i < 40:
        r = routes[(sum(ord(c) for c in slug) + 11 * i) % len(routes)]
        if r.split('/')[-1] != slug and r not in out:
            out.append(r)
        i += 1
    return out

def movie(slug, h2, para, items, seed):
    see = links(slug, MOVIE_SEE)
    a, b = ('is the entire story', 'runs through the whole catalogue')
    if seed % 2 == 1:
        a, b = ('runs through the whole catalogue', 'is the entire story')
    items_html = ''
    for i in range(0, min(len(items) - 1, 11), 2):
        items_html += f'      <li class="tl-item"><span class="li-lead">{items[i]}</span> {items[i+1]}</li>\n'
    see_html = ''
    if see:
        l0 = see[0].split('/')[-1].replace('-', ' ').title()
        l1 = see[1].split('/')[-1].replace('-', ' ').title()
        see_html = f'      <p class="see-also">See also: <a href="/{see[0]}">{l0}</a> and <a href="/{see[1]}">{l1}</a> for neighbouring nights.</p>\n'
    return (f'  <section class="see-also-sec" data-esrc="t8">\n'
            f'    <h2>{h2}</h2>\n'
            f'    <p>{para} {a[:1].upper() + a[1:]} {b[:1].upper() + b[1:]}.</p>\n'
            f'    <ul class="thread-list">\n{items_html}    </ul>\n'
            f'{see_html}  </section>\n')

def ed(slug, desk, h2, para, items, para2):
    see = see3(slug, DESK_SEE.get(desk, MOVIE_SEE))
    items_html = ''
    for i in range(0, len(items) - 1, 2):
        items_html += f'      <li class="tl-item"><span class="li-lead">{items[i]}</span> {items[i+1]}</li>\n'
    see_html = ''
    if len(see) == 3:
        labels = [r.split('/')[-1].replace('-', ' ').title() for r in see]
        see_html = (f'      <p class="see-also">See also: <a href="/{see[0]}">{labels[0]}</a>, '
                    f'<a href="/{see[1]}">{labels[1]}</a> and <a href="/{see[2]}">{labels[2]}</a> for more of the reading pile.</p>\n')
    return (f'  <section class="see-also-sec" data-esrc="t8">\n'
            f'    <h2>{h2}</h2>\n'
            f'    <p>{para}</p>\n'
            f'    <ul class="thread-list">\n{items_html}    </ul>\n'
            f'    <p>{para2}</p>\n'
            f'{see_html}  </section>\n')

